using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF 9 changed the discriminator property from "Discriminator" to "$type".
            // Preserve the old name so existing 500K documents remain readable
            // and direct SQL queries against c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF 9 changed the id format from "EntityType|Key" to just "Key".
            // Preserve the old format so existing documents are found by key.
            entity.HasIdProperty("id");
            entity.Property<string>("__id")
                  .ToJsonProperty("id");
            // Use a value converter to keep the "Product|{Id}" format
        });

        // Cosmos DB provider does not support indexes — removed HasIndex call.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF 9 Cosmos provider removed synchronous query support.
        // All queries must use async APIs (ToListAsync, FirstAsync, etc.).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

