using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator renamed to "$type" in EF 9.
            // Existing docs have "Discriminator" and direct SQL queries reference it.
            // Preserve the EF 8 property name so 500K existing documents stay readable.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id format changed from "EntityType|Key" to just "Key".
            // Existing documents use "Product|123". Map the JSON "id" to a shadow property
            // with a value generator that reproduces the EF 8 format.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdGenerator>();
            entity.HasIdProperty("__id");

            // BREAKING CHANGE 3 — HasIndex is not supported by the Cosmos provider.
            // It was silently ignored in EF 8 but may throw in EF 9. Removed.
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // BREAKING CHANGE 4 — Sync query APIs (.ToList(), .First(), etc.) removed.
        // All queries must use async equivalents (.ToListAsync(), .FirstAsync()).
    }
}

/// <summary>
/// Reproduces the EF Core 8 Cosmos id format: "EntityType|KeyValue".
/// </summary>
class LegacyIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

